    "coverImage": "/wp-media/uploads/2026/02/modern-home-with-newly-installed-energy-efficient-windows-showcasing-various-styles-e7ecdbe1-4ccf-4590-86f7-caf67f16acd1.jpg",
    "coverAlt": "Modern home with newly installed energy-efficient windows showcasing various styles",
