    "coverImage": "/wp-media/uploads/2026/03/cozy-seattle-home-with-modern-windows-and-skyline-view-emphasizing-window-replacement-benefits-c6d241b3-ad66-4eb3-8c31-661a17519634.jpg",
    "coverAlt": "Cozy Seattle home with modern windows and skyline view, emphasizing window replacement benefits",
